  // Gestures: mobile bottom-sheet (swipe up/down); desktop right sheet (edge swipe).
  (function bindSessionDrawerGestures(){
    var sx=0,sy=0,tracking=false,mode=null;
    function isWide(){ return window.matchMedia('(min-width:760px)').matches; }
    function isOpen(){ return drawer.classList.contains('open'); }
    document.addEventListener('touchstart', function(e){
      if(e.touches.length!==1) return;
      var t=e.touches[0];
      sx=t.clientX; sy=t.clientY; mode=null; tracking=false;
      if(isWide()){
        if(!isOpen() && sx>=window.innerWidth-28){ mode='open-right'; tracking=true; }
        else if(isOpen() && e.target.closest && (e.target.closest('.sheet') || e.target.closest('.shade'))){ mode='close-right'; tracking=true; }
      } else {
        if(!isOpen() && sy>=window.innerHeight-36){ mode='open-up'; tracking=true; }
        else if(isOpen() && e.target.closest && (e.target.closest('.sheet') || e.target.closest('.shade') || e.target.closest('.grab'))){ mode='close-down'; tracking=true; }
      }
    }, {passive:true});
    document.addEventListener('touchmove', function(e){
      if(!tracking || !e.touches.length || !mode) return;
      var t=e.touches[0], dx=t.clientX-sx, dy=t.clientY-sy;
      if(mode==='open-right' && dx<-56 && Math.abs(dx)>Math.abs(dy)*1.1){ openSessionsDrawer(); tracking=false; e.preventDefault(); }
      else if(mode==='close-right' && dx>56 && Math.abs(dx)>Math.abs(dy)*1.1){ closeSessionsDrawer(); tracking=false; e.preventDefault(); }
      else if(mode==='open-up' && dy<-56 && Math.abs(dy)>Math.abs(dx)*1.1){ openSessionsDrawer(); tracking=false; e.preventDefault(); }
      else if(mode==='close-down' && dy>56 && Math.abs(dy)>Math.abs(dx)*1.1){ closeSessionsDrawer(); tracking=false; e.preventDefault(); }
    }, {passive:false});
    document.addEventListener('touchend', function(){ tracking=false; mode=null; }, {passive:true});
    document.addEventListener('touchcancel', function(){ tracking=false; mode=null; }, {passive:true});
  })();
